// ============================================================
// Icamax op_kernel
// BLAS Level 1: 复数向量最大绝对值索引查找
// 计算: argmax_i |Re(x[i*incx])| + |Im(x[i*incx])|, 返回 1-based int32 索引
// ============================================================

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

class KernelIcamax {
public:
    __aicore__ inline KernelIcamax() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR output,
                                 int64_t totalLength, int64_t incx,
                                 int64_t tileLength, int64_t dtypeSize)
    {
        this->totalLength = totalLength;
        this->incx = incx;
        this->tileLength = tileLength;
        this->dtypeSize = dtypeSize;
        // 使用 float 作为比较基准 (complex128 的 double 分量也转为 float 比较)
        this->maxVal = -3.402823466e+38f;
        this->maxIdx = -1;

        // GlobalTensor: 输入复数向量按分量类型访问
        // complex64: float* (2*totalLength*incx floats), complex128: float* (4*totalLength*incx floats)
        if (dtypeSize == 8) {  // complex64
            xGm.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(x), 2 * totalLength * incx);
        } else {  // complex128: 按 float 视图访问 (2倍分量数)
            xGm.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(x), 4 * totalLength * incx);
        }
        outGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(output), 1);

        // UB: 输入缓冲区
        // complex64: 2*tileLength*incx floats; complex128: 4*tileLength*incx floats
        int64_t floatCount = (dtypeSize == 8) ? (2 * tileLength * incx) : (4 * tileLength * incx);
        pipe.InitBuffer(inQueueX, BUFFER_NUM, floatCount * sizeof(float));

        // UB: 输出缓冲区 (1 个 int32)
        pipe.InitBuffer(outBuf, sizeof(int32_t));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->totalLength + this->tileLength - 1) / this->tileLength;

        for (int64_t i = 0; i < tileNum; ++i) {
            int64_t tileStart = i * this->tileLength;
            int64_t curTileLen = this->tileLength;
            if (i == tileNum - 1) {
                curTileLen = this->totalLength - tileStart;
            }
            // 对齐到 32B 边界 (8 个 float)
            int64_t floatsPerElem = (this->dtypeSize == 8) ? (2 * this->incx) : (4 * this->incx);
            int64_t alignedFloatCount = ((curTileLen * floatsPerElem + 7) / 8) * 8;

            CopyIn(i, alignedFloatCount);
            Compute(i, curTileLen, tileStart);
        }

        CopyOut();
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t floatCount)
    {
        // 计算 GM 偏移: progress * tileLength * incx 个复数
        int64_t floatsPerElem = (this->dtypeSize == 8) ? 2 : 4;
        int64_t gmFloatOffset = progress * this->tileLength * this->incx * floatsPerElem;

        AscendC::LocalTensor<float> xLocal = inQueueX.AllocTensor<float>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(floatCount * sizeof(float)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<float> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[gmFloatOffset], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLen, int64_t tileStart)
    {
        AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();

        // 逐元素处理: 提取实部/虚部, 计算 |real| + |imag|, 跟踪最大值
        // 所有中间计算使用 float (complex128 的 double 分量也转为 float 比较)
        int64_t floatsPerElem = (this->dtypeSize == 8) ? 2 : 4;
        int64_t strideFloats = floatsPerElem * this->incx;

        for (int64_t j = 0; j < curTileLen; ++j) {
            int64_t base = j * strideFloats;
            float real = xLocal.GetValue(base);
            float imag = xLocal.GetValue(base + 1);

            float absReal = (real < 0.0f) ? -real : real;
            float absImag = (imag < 0.0f) ? -imag : imag;
            float absSum = absReal + absImag;

            if (absSum > this->maxVal) {
                this->maxVal = absSum;
                this->maxIdx = tileStart + j;
            }
        }

        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut()
    {
        // 计算最终 1-based 索引
        int64_t finalIndex = this->maxIdx * this->incx + 1;
        int32_t outputVal = static_cast<int32_t>(finalIndex);

        AscendC::LocalTensor<int32_t> outLocal = outBuf.Get<int32_t>();
        outLocal.SetValue(0, outputVal);

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(int32_t)), 0, 0, 0};
        AscendC::DataCopyPad(outGm, outLocal, copyParams);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outBuf;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<int32_t> outGm;

    int64_t totalLength;
    int64_t incx;
    int64_t tileLength;
    int64_t dtypeSize;

    float maxVal;
    int64_t maxIdx;
};

extern "C" __global__ __aicore__ void icamax(GM_ADDR x, GM_ADDR output,
                                               int64_t totalLength, int64_t incx,
                                               int64_t tileLength, int64_t dtypeSize)
{
    KernelIcamax op;
    op.Init(x, output, totalLength, incx, tileLength, dtypeSize);
    op.Process();
}

