// ============================================================
// Icamax op_host
// Host 端: tiling 计算 + kernel launch
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_icamax.h"

namespace ascend_kernel {

at::Tensor icamax(const at::Tensor &x, int64_t n, int64_t incx)
{
    // ---- 输入校验 ----
    TORCH_CHECK(x.scalar_type() == at::kComplexFloat || x.scalar_type() == at::kComplexDouble,
                "icamax: only complex64 and complex128 are supported, got ", x.scalar_type());
    TORCH_CHECK(x.dim() == 1, "icamax: only 1D input is supported, got ", x.dim(), "D");
    TORCH_CHECK(x.is_contiguous(), "icamax: input tensor must be contiguous");
    TORCH_CHECK(n >= 1, "icamax: n must be >= 1, got ", n);
    TORCH_CHECK(incx >= 1, "icamax: incx must be >= 1, got ", incx);
    TORCH_CHECK(n * incx <= x.numel(), "icamax: n*incx exceeds input size, n=", n, " incx=", incx,
                " numel=", x.numel());

    // ---- 输出: 标量 int32 ----
    auto output = at::empty({1}, at::TensorOptions().dtype(at::kInt).device(x.device()));

    int64_t totalLength = n;
    int64_t dtypeSize = x.element_size();  // 8 for complex64, 16 for complex128
    int64_t componentSize = dtypeSize / 2; // 4 for float, 8 for double

    // ---- 获取硬件参数 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- UB 级 tiling ----
    // bufferCoefficient = 每逻辑元素在 UB 中总占用字节
    //   inQueueX: BUFFER_NUM(2) * incx * sizeof(complex<T>)
    //   = 2 * incx * dtypeSize
    int64_t bufferCoefficient = 2 * incx * dtypeSize;
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (maxTileElements < 1) { maxTileElements = 1; }
    if (componentSize == 0) { componentSize = 1; }
    // 32B 对齐: 按分量数对齐
    int64_t alignElements = 32 / componentSize;
    if (alignElements < 1) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < 1) { tileLength = 1; }

    uint32_t blockDim = 1;  // 单核处理

    // ---- EXEC_KERNEL_CMD: 所有参数必须是左值 ----
    int64_t incxLocal = incx;
    int64_t nLocal = n;
    int64_t tileLenLocal = tileLength;
    int64_t dtypeSizeLocal = dtypeSize;

    EXEC_KERNEL_CMD(icamax, blockDim, x, output,
                    nLocal, incxLocal, tileLenLocal, dtypeSizeLocal);

    return output;
}

}  // namespace ascend_kernel

