// ============================================================
// Isamin op_kernel
// BLAS Level 1: 向量绝对值最小索引查找
// 计算: argmin_i |x[i*incx]|, 返回 1-based int32 索引
// ============================================================

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

class KernelIsamin {
public:
    __aicore__ inline KernelIsamin() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR output,
                                 int64_t totalLength, int64_t incx,
                                 int64_t tileLength, int64_t dtypeSize)
    {
        this->totalLength = totalLength;
        this->incx = incx;
        this->tileLength = tileLength;
        this->dtypeSize = dtypeSize;
        this->minVal = 3.402823466e+38f;
        this->minIdx = -1;

        // GlobalTensor: 输入向量
        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(x), totalLength * incx);
        outGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(output), 1);

        // UB: 输入缓冲区
        // float16/bf16: tileLength*incx 个 half (2 bytes each)
        // float32: tileLength*incx 个 float (4 bytes each)
        int64_t elemCount = tileLength * incx;
        pipe.InitBuffer(inQueueX, BUFFER_NUM, elemCount * dtypeSize);

        // UB: FP32 计算缓冲区 (仅 fp16/bf16 需要)
        if (dtypeSize == 2) {
            pipe.InitBuffer(castBuf, elemCount * sizeof(float));
        }

        // UB: 输出缓冲区 (1 个 int32)
        pipe.InitBuffer(outBuf, sizeof(int32_t));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->totalLength + this->tileLength - 1) / this->tileLength;

        for (int64_t i = 0; i < tileNum; ++i) {
            int64_t tileStart = i * this->tileLength;
            int64_t curTileLen = this->tileLength;
            if (i == tileNum - 1) {
                curTileLen = this->totalLength - tileStart;
            }
            // 对齐到 32B 边界
            int64_t loadElemCount = curTileLen * this->incx;
            if (this->dtypeSize == sizeof(float)) {
                loadElemCount = ((loadElemCount + 7) / 8) * 8;  // 32B / 4 = 8 floats
            } else {
                loadElemCount = ((loadElemCount + 15) / 16) * 16;  // 32B / 2 = 16 half
            }

            CopyIn(i, loadElemCount);
            Compute(i, curTileLen, tileStart);
        }

        CopyOut();
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t elemCount)
    {
        int64_t gmOffset = progress * this->tileLength * this->incx;

        AscendC::LocalTensor<half> xLocal = inQueueX.AllocTensor<half>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(elemCount * this->dtypeSize), 0, 0, 0};
        AscendC::DataCopyPadExtParams<half> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[gmOffset], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLen, int64_t tileStart)
    {
        AscendC::LocalTensor<half> xLocal = inQueueX.DeQue<half>();

        if (this->dtypeSize == sizeof(float)) {
            // float32: 直接 Abs 后标量循环
            const float *xFloat = reinterpret_cast<const float *>(xLocal.GetPhyAddr());
            int64_t stride = this->incx;

            for (int64_t j = 0; j < curTileLen; ++j) {
                float val = xFloat[j * stride];
                float absVal = (val < 0.0f) ? -val : val;
                if (absVal < this->minVal) {
                    this->minVal = absVal;
                    this->minIdx = tileStart + j;
                }
            }
        } else {
            // float16/bf16: Cast 升精度到 FP32
            AscendC::LocalTensor<float> xLocalFp32 = castBuf.Get<float>();
            AscendC::Cast(xLocalFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLen * this->incx);

            int64_t stride = this->incx;

            for (int64_t j = 0; j < curTileLen; ++j) {
                float val = xLocalFp32.GetValue(j * stride);
                float absVal = (val < 0.0f) ? -val : val;
                if (absVal < this->minVal) {
                    this->minVal = absVal;
                    this->minIdx = tileStart + j;
                }
            }
        }

        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut()
    {
        int64_t finalIndex = this->minIdx * this->incx + 1;
        int32_t outputVal = static_cast<int32_t>(finalIndex);

        AscendC::LocalTensor<int32_t> outLocal = outBuf.Get<int32_t>();
        outLocal.SetValue(0, outputVal);

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(int32_t)), 0, 0, 0};
        AscendC::DataCopyPad(outGm, outLocal, copyParams);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outBuf;
    AscendC::GlobalTensor<half> xGm;
    AscendC::GlobalTensor<int32_t> outGm;

    int64_t totalLength;
    int64_t incx;
    int64_t tileLength;
    int64_t dtypeSize;

    float minVal;
    int64_t minIdx;
};

extern "C" __global__ __aicore__ void isamin(GM_ADDR x, GM_ADDR output,
                                               int64_t totalLength, int64_t incx,
                                               int64_t tileLength, int64_t dtypeSize)
{
    KernelIsamin op;
    op.Init(x, output, totalLength, incx, tileLength, dtypeSize);
    op.Process();
}
