        this->tileLength = tileLength;
        this->dtypeSize = dtypeSize;
        this->minVal = 3.402823466e+38f;
        this->minIdx = -1;

        // 统一使用 half* 视图: float32 的 1 个元素 = 2 个 half 位置
        int64_t halfPerElem = (dtypeSize == sizeof(float)) ? 2 : 1;
        int64_t gmHalfCount = totalLength * incx * halfPerElem;
        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(x), gmHalfCount);
        outGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(output), 1);

        int64_t halfPerTile = tileLength * incx * halfPerElem;
        pipe.InitBuffer(inQueueX, BUFFER_NUM, halfPerTile * sizeof(half));

        if (dtypeSize == sizeof(float)) {
            pipe.InitBuffer(tmpBuf, tileLength * incx * sizeof(float));
        } else {
            pipe.InitBuffer(tmpBuf, tileLength * incx * sizeof(float));
        }
        pipe.InitBuffer(outBuf, sizeof(int32_t));
    }

    __aicore__ inline void Process()
    {
        int64_t halfPerElem = (this->dtypeSize == sizeof(float)) ? 2 : 1;
        int64_t tileNum = (this->totalLength + this->tileLength - 1) / this->tileLength;

        for (int64_t i = 0; i < tileNum; ++i) {
            int64_t tileStart = i * this->tileLength;
            int64_t curTileLen = this->tileLength;
            if (i == tileNum - 1) {
                curTileLen = this->totalLength - tileStart;
            }

            int64_t loadHalfCount = curTileLen * this->incx * halfPerElem;
            int64_t alignTo = 32 / sizeof(half);  // 16
            loadHalfCount = ((loadHalfCount + alignTo - 1) / alignTo) * alignTo;

            CopyIn(i, loadHalfCount);
            Compute(i, curTileLen, tileStart);
        }

        CopyOut();
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t halfCount)
    {
        int64_t halfPerElem = (this->dtypeSize == sizeof(float)) ? 2 : 1;
        int64_t gmHalfOffset = progress * this->tileLength * this->incx * halfPerElem;

        AscendC::LocalTensor<half> xLocal = inQueueX.AllocTensor<half>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(halfCount * sizeof(half)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<half> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[gmHalfOffset], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLen, int64_t tileStart)
    {
        AscendC::LocalTensor<half> xLocal = inQueueX.DeQue<half>();

        if (this->dtypeSize == sizeof(float)) {
            // float32: xLocal 中是成对的 half, 每 2 个 half = 1 个 float
            const float *xFloat = reinterpret_cast<const float *>(xLocal.GetPhyAddr());
