    AscendC::GlobalTensor<int32_t> outGm;

    int64_t totalLength;
    int64_t incx;
    int64_t tileLength;
    int64_t dtypeSize;

    float minVal;
    int64_t minIdx;
};

extern "C" __global__ __aicore__ void isamin(GM_ADDR x, GM_ADDR output,
