// ============================================================
// Isamin op_host
// Host 端: tiling 计算 + kernel launch
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_isamin.h"

namespace ascend_kernel {

at::Tensor isamin(const at::Tensor &x, int64_t n, int64_t incx)
{
    // ---- 输入校验 ----
    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
                "isamin: only float32, float16 and bfloat16 are supported, got ", x.scalar_type());
    TORCH_CHECK(x.dim() == 1, "isamin: only 1D input is supported, got ", x.dim(), "D");
    TORCH_CHECK(x.is_contiguous(), "isamin: input tensor must be contiguous");
    TORCH_CHECK(n >= 1, "isamin: n must be >= 1, got ", n);
    TORCH_CHECK(incx >= 1, "isamin: incx must be >= 1, got ", incx);
    TORCH_CHECK(n * incx <= x.numel(), "isamin: n*incx exceeds input size, n=", n, " incx=", incx,
                " numel=", x.numel());

    // ---- 输出: 标量 int32 ----
    auto output = at::empty({1}, at::TensorOptions().dtype(at::kInt).device(x.device()));

    int64_t totalLength = n;
    int64_t dtypeSize = x.element_size();  // 4 for float32, 2 for float16/bf16

    // ---- 获取硬件参数 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- UB 级 tiling ----
    // Unified half* GM view: float32 的 1 element = 2 half positions
    // bufferCoefficient = BUFFER_NUM(2) * incx * sizeof(half) * (dtypeSize/2)
    //                   = 2 * incx * 2 * halfPerElem = 4 * incx * halfPerElem
    // For float32: bufferCoefficient = 2 * incx * 4 = 8 * incx
    // For float16: bufferCoefficient = 2 * incx * 2 = 4 * incx
    int64_t halfPerElem = (dtypeSize == sizeof(float)) ? 2 : 1;
    int64_t bufferCoefficient = 2 * incx * sizeof(half) * halfPerElem;
    // Add tmpBuf for float: tileLength * incx * sizeof(float) = tileLength * incx * 4
    // Per logical element: incx * 4 bytes
    bufferCoefficient += incx * sizeof(float);
    // Add outBuf: always 4 bytes, negligible for tiling

    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (maxTileElements < 1) { maxTileElements = 1; }

    // 32B 对齐
    int64_t alignElements = 32 / sizeof(half);  // 16
    if (alignElements < 1) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < 1) { tileLength = 1; }

    uint32_t blockDim = 1;  // 单核处理

    // ---- EXEC_KERNEL_CMD: 所有参数必须是左值 ----
    int64_t incxLocal = incx;
    int64_t nLocal = n;
    int64_t tileLenLocal = tileLength;
    int64_t dtypeSizeLocal = dtypeSize;

    EXEC_KERNEL_CMD(isamin, blockDim, x, output,
                    nLocal, incxLocal, tileLenLocal, dtypeSizeLocal);

    return output;
}

}  // namespace ascend_kernel
