#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

class KernelIsamin {
public:
    __aicore__ inline KernelIsamin() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR output,
                                 int64_t totalLength, int64_t incx,
                                 int64_t tileLength, int64_t dtypeSize)
    {
        this->totalLength = totalLength;
        this->incx = incx;
        this->tileLength = tileLength;
        this->dtypeSize = dtypeSize;
        this->minVal = 3.402823466e+38f;
        this->minIdx = -1;

        // 统一使用 half* GM 视图
        // fp32: 1 float = 2 half positions
        // fp16/bf16: 1 element = 1 half position
        this->halfPerElem = (dtypeSize == sizeof(float)) ? 2 : 1;
        int64_t gmHalfCount = totalLength * incx * this->halfPerElem;
        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(x), gmHalfCount);
        outGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(output), 1);

        int64_t halfPerTile = tileLength * incx * this->halfPerElem;
        pipe.InitBuffer(inQueueX, BUFFER_NUM, halfPerTile * sizeof(half));

        pipe.InitBuffer(tmpBuf, tileLength * incx * sizeof(float));
        pipe.InitBuffer(outBuf, sizeof(int32_t));
    }

    __aicore__ inline void Process()
    {
        int64_t gmHalfTotal = this->totalLength * this->incx * this->halfPerElem;
        int64_t tileNum = (this->totalLength + this->tileLength - 1) / this->tileLength;

        for (int64_t i = 0; i < tileNum; ++i) {
            int64_t tileStart = i * this->tileLength;
            int64_t curTileLen = this->tileLength;
            if (i == tileNum - 1) {
                curTileLen = this->totalLength - tileStart;
            }

            int64_t needHalfCount = curTileLen * this->incx * this->halfPerElem;
            int64_t gmHalfOffset = i * this->tileLength * this->incx * this->halfPerElem;
            int64_t remainHalf = gmHalfTotal - gmHalfOffset;
            if (needHalfCount > remainHalf) {
                needHalfCount = remainHalf;
            }

            CopyIn(i, needHalfCount);
            Compute(i, curTileLen, tileStart);
        }

        CopyOut();
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t halfCount)
    {
        int64_t gmHalfOffset = progress * this->tileLength * this->incx * this->halfPerElem;

        int64_t actualCount = halfCount;
        // 对齐到 32B (=16 half) 但不超出 GM buffer
