        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(actualCount * sizeof(half)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<half> padParams{true, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[gmHalfOffset], copyParams, padParams);
