    }

    __aicore__ inline void CopyOut()
    {
        int64_t finalIndex = this->minIdx * this->incx + 1;
        int32_t outputVal = static_cast<int32_t>(finalIndex);

        AscendC::LocalTensor<int32_t> outLocal = outBuf.Get<int32_t>();
        outLocal.SetValue(0, outputVal);

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(int32_t)), 0, 0, 0};
        AscendC::DataCopyPad(outGm, outLocal, copyParams);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outBuf;
    AscendC::GlobalTensor<half> xGm;
    AscendC::GlobalTensor<int32_t> outGm;

