// ============================================================
// Isamin op_kernel
// BLAS Level 1: 向量绝对值最小索引查找
// 计算: argmin_i |x[i*incx]|, 返回 1-based int32 索引
// 支持 float32, float16, bfloat16
// ============================================================

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

class KernelIsamin {
public:
    __aicore__ inline KernelIsamin() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR output,
                                 int64_t totalLength, int64_t incx,
                                 int64_t tileLength, int64_t dtypeSize)
    {
        this->totalLength = totalLength;
        this->incx = incx;
        this->tileLength = tileLength;
        this->dtypeSize = dtypeSize;
        this->minVal = 3.402823466e+38f;
        this->minIdx = -1;

        // 使用 int8_t (字节级) GM 视图，避免类型转换问题
        int64_t gmByteCount = totalLength * incx * dtypeSize;
        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(x), gmByteCount);
        outGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(output), 1);

        int64_t tileByteCount = tileLength * incx * dtypeSize;
        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileByteCount);

        int64_t fp32BufCount = tileLength * incx;
        pipe.InitBuffer(fp32Buf, fp32BufCount * sizeof(float));
        pipe.InitBuffer(outBuf, sizeof(int32_t));
    }

    __aicore__ inline void Process()
    {
        int64_t gmByteTotal = this->totalLength * this->incx * this->dtypeSize;
        int64_t tileNum = (this->totalLength + this->tileLength - 1) / this->tileLength;

        for (int64_t i = 0; i < tileNum; ++i) {
            int64_t tileStart = i * this->tileLength;
            int64_t curTileLen = this->tileLength;
            if (i == tileNum - 1) {
                curTileLen = this->totalLength - tileStart;
            }

            int64_t needBytes = curTileLen * this->incx * this->dtypeSize;
            int64_t gmByteOffset = i * this->tileLength * this->incx * this->dtypeSize;
            int64_t remainBytes = gmByteTotal - gmByteOffset;
            if (needBytes > remainBytes) {
                needBytes = remainBytes;
            }

            CopyIn(i, needBytes);
            Compute(curTileLen, tileStart);
        }

        CopyOut();
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t byteCount)
    {
        int64_t gmByteOffset = progress * this->tileLength * this->incx * this->dtypeSize;

        AscendC::LocalTensor<int8_t> xLocal = inQueueX.AllocTensor<int8_t>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(byteCount), 0, 0, 0};
        AscendC::DataCopyPadExtParams<int8_t> padParams{true, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[gmByteOffset], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t curTileLen, int64_t tileStart)
    {
        AscendC::LocalTensor<int8_t> xLocalBytes = inQueueX.DeQue<int8_t>();

        if (this->dtypeSize == sizeof(float)) {
            AscendC::LocalTensor<float> xLocalFloat = xLocalBytes.ReinterpretCast<float>();
            int64_t stride = this->incx;

            for (int64_t j = 0; j < curTileLen; ++j) {
                float val = xLocalFloat.GetValue(j * stride);
                float absVal = (val < 0.0f) ? -val : val;
                if (absVal < this->minVal) {
                    this->minVal = absVal;
                    this->minIdx = tileStart + j;
                }
            }
        } else {
            AscendC::LocalTensor<half> xLocalHalf = xLocalBytes.ReinterpretCast<half>();
            AscendC::LocalTensor<float> xLocalFp32 = fp32Buf.Get<float>();
            AscendC::Cast(xLocalFp32, xLocalHalf, AscendC::RoundMode::CAST_NONE, curTileLen * this->incx);

            int64_t stride = this->incx;

            for (int64_t j = 0; j < curTileLen; ++j) {
                float val = xLocalFp32.GetValue(j * stride);
                float absVal = (val < 0.0f) ? -val : val;
                if (absVal < this->minVal) {
                    this->minVal = absVal;
                    this->minIdx = tileStart + j;
                }
            }
        }

        inQueueX.FreeTensor(xLocalBytes);
    }

    __aicore__ inline void CopyOut()
    {
        int64_t finalIndex = this->minIdx * this->incx + 1;
        int32_t outputVal = static_cast<int32_t>(finalIndex);

        AscendC::LocalTensor<int32_t> outLocal = outBuf.Get<int32_t>();
        outLocal.SetValue(0, outputVal);

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(int32_t)), 0, 0, 0};
        AscendC::DataCopyPad(outGm, outLocal, copyParams);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> fp32Buf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outBuf;
    AscendC::GlobalTensor<int8_t> xGm;
    AscendC::GlobalTensor<int32_t> outGm;

    int64_t totalLength;
    int64_t incx;
    int64_t tileLength;
    int64_t dtypeSize;

    float minVal;
    int64_t minIdx;
};

extern "C" __global__ __aicore__ void isamin(GM_ADDR x, GM_ADDR output,
                                               int64_t totalLength, int64_t incx,
                                               int64_t tileLength, int64_t dtypeSize)
{
    KernelIsamin op;
    op.Init(x, output, totalLength, incx, tileLength, dtypeSize);
    op.Process();
}
